function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Sky
  brush.fill("#99ccff", 30); brush.beginShape();
  brush.vertex(0, 0); brush.vertex(400, 0); brush.vertex(400, 200); brush.vertex(0, 200);
  brush.endShape(true);

  // Hills
  brush.fill("#80cc88", 60); brush.beginShape();
  brush.vertex(0, 200); brush.vertex(200, 100); brush.vertex(400, 200); brush.vertex(200, 300);
  brush.endShape(true);

  // Trees on the hill
  brush.fill("#406040", 100); brush.beginShape();
  brush.vertex(0, 150); brush.vertex(20, 50); brush.vertex(40, 100); brush.vertex(20, 150);
  brush.endShape(true);

  // Road
  brush.fill("#333333", 60); brush.beginShape();
  brush.vertex(0, 250); brush.vertex(200, 250); brush.vertex(400, 250); brush.vertex(200, 300);
  brush.endShape(true);

  // Water below
  brush.fill("#336699", 50); brush.beginShape();
  brush.vertex(0, 350); brush.vertex(400, 350); brush.vertex(400, 400); brush.vertex(0, 400);
  brush.endShape(true);
}
