function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  noFill();
  stroke("#b35f4d");
  strokeWeight(2);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  push();
  translate(200, 0);
  for (let i = 0; i < 200; i++) {
    let x = map(i, 0, 200, 0, width);
    let y = map(i, 0, 200, height, 0);
    brush.fillBleed(0.1);
    brush.circle(x, y, 2);
  }
  pop();
  brush.fillBleed(0.4);
  brush.fillTexture(0.7, 0);
  brush.beginPath();
  brush.moveTo(0, 0);
  brush.quadraticCurveTo(100, 50, 200, 0);
  brush.lineTo(200, 200);
  brush.quadraticCurveTo(300, 50, 400, 0);
  brush.closePath();
  brush.fill();
  brush.fillTexture(0.7, 1);
  brush.beginShape(CURVATURE);
  brush.vertex(0, 0);
  brush.vertex(100, 50);
  brush.vertex(200, 0);
  brush.vertex(300, 50);
  brush.vertex(400, 0);
  brush.endShape(true);
}
