  brush.fill("#e08a72", 0.3);

  // Sky
  brush.fill("#d2e3e3", 0.3);
  brush.fill("#e9e9e9", 0.2);

  // Hills
  brush.fillTexture(0.9, true);
  for (let i = 0; i < 10; i++) {
    brush.vertex(200 + i * 25, 150);
    brush.vertex(200 + i * 25, 180);
  }
  brush.endShape(true);

  // Mountaintops
  brush.fillTexture(0.8, true);
  for (let i = 0; i < 4; i++) {
